function draw(){
 ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#1a3336');sky.addColorStop(.55,'#142527');sky.addColorStop(1,'#111a1c');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
 ctx.save();ctx.translate(W/2-camera.x,H/2-camera.y);drawCity();drawMarkers();traffic.forEach(c=>drawCar(c.x,c.y,c.a,c.color,false));police.forEach((p,i)=>drawCar(p.x,p.y,p.a,'#dfe5dc',true,i));drawCar(player.x,player.y,player.a,'#f06b80',false,0,true);ctx.restore();drawMinimap();drawEdgeArrow();
}
function drawCity(){let viewL=camera.x-W/2-100,viewT=camera.y-H/2-100,viewR=camera.x+W/2+100,viewB=camera.y+H/2+100;
 // Warm blocks and coastal dark ground
 ctx.fillStyle='#192e2d';ctx.fillRect(0,0,WORLD,WORLD);
 for(let gy=0;gy<5;gy++)for(let gx=0;gx<5;gx++){let bx=ROAD_OFFSET+gx*STEP+ROAD/2,by=ROAD_OFFSET+gy*STEP+ROAD/2,bw=STEP-ROAD,bh=STEP-ROAD;ctx.fillStyle=(gx+gy)%2?'#253532':'#293a34';ctx.fillRect(bx,by,bw,bh);ctx.strokeStyle='#34463e';ctx.lineWidth=2;ctx.strokeRect(bx+8,by+8,bw-16,bh-16)}
 // Roads and sidewalks
 ctx.fillStyle='#49504d';for(let i=0;i<5;i++){let p=roadCenter(i);ctx.fillRect(p-ROAD/2,0,ROAD,WORLD);ctx.fillRect(0,p-ROAD/2,WORLD,ROAD)}
 ctx.fillStyle='#a5a18a';for(let i=0;i<5;i++){let p=roadCenter(i);ctx.fillRect(p-ROAD/2,0,4,WORLD);ctx.fillRect(p+ROAD/2-4,0,4,WORLD);ctx.fillRect(0,p-ROAD/2,WORLD,4);ctx.fillRect(0,p+ROAD/2-4,WORLD,4)}
 // lane marks
 ctx.save();ctx.setLineDash([22,22]);ctx.strokeStyle='#d5c8876e';ctx.lineWidth=2;for(let i=0;i<5;i++){let p=roadCenter(i);ctx.beginPath();ctx.moveTo(p,0);ctx.lineTo(p,WORLD);ctx.stroke();ctx.beginPath();ctx.moveTo(0,p);ctx.lineTo(WORLD,p);ctx.stroke()}ctx.restore();
 // Crosswalks at intersections
 for(let a=0;a<5;a++)for(let b=0;b<5;b++){let x=roadCenter(a),y=roadCenter(b);ctx.fillStyle='#ddd7b64f';for(let k=-4;k<=4;k++){ctx.fillRect(x+k*9-1,y-ROAD/2+10,3,18);ctx.fillRect(x-ROAD/2+10,y+k*9-1,18,3)}}
 // Neon puddle accents
 for(let i=0;i<5;i++)for(let j=0;j<5;j++){let x=roadCenter(i)+((i*71+j*33)%50)-25,y=roadCenter(j)+((j*47+i*29)%50)-25;ctx.fillStyle='rgba(77,213,198,.08)';ctx.beginPath();ctx.ellipse(x,y,16,5,-.4,0,Math.PI*2);ctx.fill()}
 for(const p of parks){ctx.fillStyle='#183d37';ctx.fillRect(p.x,p.y,p.w,p.h);ctx.strokeStyle='#4aa58a55';ctx.lineWidth=2;ctx.strokeRect(p.x+8,p.y+8,p.w-16,p.h-16);ctx.fillStyle='#315449';ctx.fillRect(p.x+p.w*.45,p.y+12,p.w*.1,p.h-24);ctx.fillRect(p.x+12,p.y+p.h*.46,p.w-24,p.h*.08)}
 for(const b of buildings){if(b.x+b.w<viewL||b.x>viewR||b.y+b.h<viewT||b.y>viewB)continue;let colors=[['#314447','#3a5050'],['#4a3c3b','#5b4742'],['#343c4a','#454e5c'],['#3c4840','#4c5a4a'],['#493e4e','#58495a']][b.tone];ctx.fillStyle='#09141670';ctx.fillRect(b.x+9,b.y+12,b.w,b.h);ctx.fillStyle=colors[0];ctx.fillRect(b.x,b.y,b.w,b.h);ctx.fillStyle=colors[1];ctx.fillRect(b.x+7,b.y+7,b.w-14,b.h-14);ctx.strokeStyle='#d8cda833';ctx.lineWidth=2;ctx.strokeRect(b.x+8,b.y+8,b.w-16,b.h-16);
 // roof geometry
 ctx.fillStyle='#1c2729';ctx.fillRect(b.x+b.w*.18,b.y+b.h*.16,b.w*.64,b.h*.17);ctx.fillStyle='#78867f22';ctx.fillRect(b.x+b.w*.2,b.y+b.h*.19,b.w*.6,3);ctx.fillStyle='#242e31';ctx.fillRect(b.x+b.w*.69,b.y+b.h*.56,b.w*.2,b.h*.25);ctx.fillStyle='#e7af6a';for(let n=0;n<Math.max(1,Math.floor(b.w/65));n++){let wx=b.x+18+n*52,wy=b.y+b.h-15;ctx.globalAlpha=.35+Math.sin(performance.now()/700+n)*.2;ctx.fillRect(wx,wy,14,3);ctx.fillRect(wx, b.y+13,3,10)}ctx.globalAlpha=1;
 }
 for(const t of palms){ctx.fillStyle='#0b1816';ctx.beginPath();ctx.ellipse(t.x+4,t.y+8,13*t.s,8*t.s,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#927a55';ctx.lineWidth=4*t.s;ctx.beginPath();ctx.moveTo(t.x,t.y+6);ctx.lineTo(t.x+2,t.y-12*t.s);ctx.stroke();ctx.fillStyle='#55a782';for(let a=0;a<7;a++){let angle=a*Math.PI/3.5;ctx.beginPath();ctx.ellipse(t.x+Math.cos(angle)*11*t.s,t.y-12*t.s+Math.sin(angle)*7*t.s,12*t.s,3*t.s,angle,0,Math.PI*2);ctx.fill()}}
 for(const c of cashDrops)if(!c.got){ctx.fillStyle='#ffcb66';ctx.shadowColor='#ffcb66';ctx.shadowBlur=14;ctx.beginPath();ctx.arc(c.x,c.y,5,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#fff0c4';ctx.fillRect(c.x-1,c.y-3,2,6)}
 // Street lamps; restrained glow circles
 for(let i=0;i<5;i++)for(let j=0;j<5;j++){let x=roadCenter(i),y=roadCenter(j);for(let dx of [-51,51])for(let dy of [-51,51]){ctx.fillStyle='#ffcf7e';ctx.globalAlpha=.38;ctx.beginPath();ctx.arc(x+dx,y+dy,2.4,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}}
}
function drawMarkers(){let target=mission.active?(mission.stage===1?mission.pickup:mission.drop):mission.pickup;let pulse=1+Math.sin(performance.now()/210)*.13;ctx.save();ctx.translate(target.x,target.y);ctx.globalAlpha=.18;ctx.fillStyle=mission.active?'#69f0dc':'#ff5e83';ctx.beginPath();ctx.arc(0,0,47*pulse,0,Math.PI*2);ctx.fill();ctx.globalAlpha=.8;ctx.strokeStyle=mission.active?'#69f0dc':'#ff5e83';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,27*pulse,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=.95;ctx.fillStyle=mission.active?'#69f0dc':'#ff5e83';ctx.beginPath();ctx.moveTo(0,-29);ctx.lineTo(11,-12);ctx.lineTo(0,-16);ctx.lineTo(-11,-12);ctx.closePath();ctx.fill();ctx.font='800 9px system-ui';ctx.textAlign='center';ctx.fillText(mission.active?(mission.stage===1?'PICKUP':'DROP'):'RUN',0,-39);ctx.restore()}
function drawCar(x,y,a,color,isCop=false,index=0,isPlayer=false){ctx.save();ctx.translate(x,y);ctx.rotate(a);ctx.fillStyle='#05090b80';ctx.beginPath();ctx.ellipse(0,4,25,15,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#12191b';ctx.fillRect(-14,-14,10,5);ctx.fillRect(6,-14,10,5);ctx.fillRect(-14,9,10,5);ctx.fillRect(6,9,10,5);ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(-22,-10,44,20,6);ctx.fill();ctx.fillStyle=isCop?'#263642':isPlayer?'#f39298':'#9eacaa';ctx.beginPath();ctx.roundRect(-8,-8,17,16,4);ctx.fill();ctx.fillStyle='#17282b';ctx.beginPath();ctx.roundRect(-5,-7,11,14,3);ctx.fill();ctx.fillStyle='#ffe5ad';ctx.fillRect(17,-7,4,4);ctx.fillRect(17,3,4,4);ctx.fillStyle='#ff3858';ctx.fillRect(-21,-7,3,4);ctx.fillRect(-21,3,3,4);
 if(isCop){let flash=Math.floor(performance.now()/170+index)%2===0;ctx.fillStyle=flash?'#ff5368':'#497aff';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=11;ctx.fillRect(-3,-8,7,3);ctx.shadowBlur=0}if(isPlayer){ctx.fillStyle='#f8b263';ctx.globalAlpha=.7;ctx.beginPath();ctx.moveTo(21,-7);ctx.lineTo(95,-19);ctx.lineTo(95,19);ctx.lineTo(21,7);ctx.closePath();let g=ctx.createLinearGradient(20,0,95,0);g.addColorStop(0,'#ffecb322');g.addColorStop(1,'#ffecb300');ctx.fillStyle=g;ctx.fill()}ctx.restore()}
function drawMinimap(){let s=142;mctx.clearRect(0,0,s,s);mctx.fillStyle='#152522';mctx.fillRect(0,0,s,s);let sc=s/WORLD;mctx.fillStyle='#555b56';for(let i=0;i<5;i++){let p=roadCenter(i)*sc;mctx.fillRect(p-ROAD*sc/2,0,ROAD*sc,s);mctx.fillRect(0,p-ROAD*sc/2,s,ROAD*sc)}mctx.fillStyle='#3c4840';for(const b of buildings)mctx.fillRect(b.x*sc,b.y*sc,b.w*sc,b.h*sc);let t=mission.active?(mission.stage===1?mission.pickup:mission.drop):mission.pickup;mctx.fillStyle=mission.active?'#69f0dc':'#ff5e83';mctx.beginPath();mctx.arc(t.x*sc,t.y*sc,3.2,0,Math.PI*2);mctx.fill();mctx.save();mctx.translate(player.x*sc,player.y*sc);mctx.rotate(player.a);mctx.fillStyle='#fff';mctx.beginPath();mctx.moveTo(4,0);mctx.lineTo(-3,-2.5);mctx.lineTo(-2,2.5);mctx.closePath();mctx.fill();mctx.restore();for(const p of police){mctx.fillStyle='#5e99ff';mctx.fillRect(p.x*sc-1,p.y*sc-1,3,3)}}
function drawEdgeArrow(){let t=mission.active?(mission.stage===1?mission.pickup:mission.drop):mission.pickup;let dx=t.x-player.x,dy=t.y-player.y,a=Math.atan2(dy,dx),r=Math.min(W,H)*.34;if(Math.abs(dx)<W*.43&&Math.abs(dy)<H*.4)return;let x=W/2+Math.cos(a)*r,y=H/2+Math.sin(a)*r;ctx.save();ctx.translate(x,y);ctx.rotate(a);ctx.fillStyle=mission.active?'#69f0dc':'#ff5e83';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=14;ctx.beginPath();ctx.moveTo(10,0);ctx.lineTo(-7,-6);ctx.lineTo(-4,0);ctx.lineTo(-7,6);ctx.closePath();ctx.fill();ctx.restore()}
})();
</script></body></html>

